def _header(headers, name):
    for key, value in headers.items():
        if key.lower() == name:
            return value
    return None


def _directives(headers):
    found = {}
    for part in (_header(headers, "cache-control") or "").split(","):
        name, eq, value = part.strip().partition("=")
        if name:
            found[name.lower()] = value.strip().strip('"') if eq else None
    return found


def _max_age(headers):
    d = _directives(headers)
    if "no-cache" in d:
        return 0
    value = d.get("max-age")
    return int(value) if value and value.isdigit() else 0


class CachingClient:
    def __init__(self, transport, clock):
        self.transport = transport
        self.clock = clock
        self.entries = {}

    def get(self, url):
        entry = self.entries.get(url)
        if entry and self.clock() < entry["fresh_until"]:
            return (200, entry["body"])
        headers = {"Accept": "application/json"}
        if entry and entry["etag"]:
            headers["If-None-Match"] = entry["etag"]
        status, resp_headers, body = self.transport.send("GET", url, headers)
        now = self.clock()
        if status == 304 and entry:
            entry["fresh_until"] = now + _max_age(resp_headers)
            etag = _header(resp_headers, "etag")
            if etag:
                entry["etag"] = etag
            return (200, entry["body"])
        if status == 200:
            if "no-store" in _directives(resp_headers):
                self.entries.pop(url, None)
            else:
                self.entries[url] = {"body": body, "etag": _header(resp_headers, "etag"), "fresh_until": now + _max_age(resp_headers)}
            return (200, body)
        return (status, body)
